// Generate series of responsive `.navbar-expand` classes for configuring
// where your navbar collapses and expands. Uses container queries so the
// navbar responds to its own width, not the viewport width.

// Mixin for expanded state styles (applied to descendants)
@mixin navbar-expanded {
  // Style the inner container since we can't style .navbar itself with container queries
  > .container,
  > .container-fluid,
  %navbar-expand-container {
    flex-wrap: nowrap;
    justify-content: flex-start;
  }

  .navbar-nav {
    --nav-link-padding-x: var(--navbar-nav-link-padding-x);
    flex-direction: row;
  }

  .navbar-toggler {
    display: none !important; // stylelint-disable-line declaration-no-important
  }

  [class*="drawer"] {
    // stylelint-disable declaration-no-important
    // Reset native <dialog> UA styles and below-breakpoint drawer styles.
    // Must use !important to override both UA <dialog> defaults and the
    // responsive drawer styles from media-breakpoint-down().
    position: static !important;
    inset: auto !important;
    z-index: auto;
    display: flex !important;
    flex-grow: 1;
    width: auto !important;
    max-width: none !important;
    height: auto !important;
    max-height: none !important;
    padding: 0;
    margin: 0;
    overflow: visible !important;
    visibility: visible !important;
    background-color: transparent !important;
    border: 0 !important;
    transform: none !important;
    @include box-shadow(none);
    @include transition(none);
    // stylelint-enable declaration-no-important

    .drawer-header {
      display: none !important; // stylelint-disable-line declaration-no-important
    }

    .drawer-body {
      display: flex;
      flex-grow: 1;
      flex-direction: row;
      align-items: center;
      padding: 0;
      overflow-y: visible;
    }
  }
}

// Always expanded (no responsive behavior)
.navbar-expand {
  @include navbar-expanded();

  // Also set on navbar itself for non-responsive case
  flex-wrap: nowrap;
  justify-content: flex-start;
}

// Responsive navbar expand classes using container queries
@include loop-breakpoints-down($navbar-breakpoints) using ($breakpoint, $next, $prefix) {
  @if $next {
    .#{$prefix}navbar-expand {
      @include container-breakpoint-up($next) {
        @include navbar-expanded();
      }
    }
  }
}

$pagination-sizes: ();
// stylelint-disable-next-line scss/dollar-variable-default
$pagination-sizes: defaults(
  ("sm", "lg"),
  $pagination-sizes
);
// scss-docs-end pagination-sizes
// stylelint-enable custom-property-no-missing-var-function

@layer components {
  .pagination {
    @include tokens($pagination-tokens);

    display: flex;
    @include list-unstyled();
  }

  .page-link {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: var(--pagination-min-height);
    padding: var(--pagination-padding-y) var(--pagination-padding-x);
    font-size: var(--pagination-font-size);
    color: var(--theme-fg, var(--pagination-color));
    text-decoration: none;
    background-color: var(--pagination-bg);
    border: var(--pagination-border-width) solid var(--pagination-border-color);
    @include transition(color .15s ease-in-out, background-color .15s ease-in-out, border-color .15s ease-in-out, box-shadow .15s ease-in-out);

    &:hover {
      z-index: 2;
      color: var(--theme-fg-emphasis, var(--pagination-hover-color));
      background-color: var(--theme-bg-subtle, var(--pagination-hover-bg));
      border-color: var(--theme-border, var(--pagination-hover-border-color));
    }

    &:focus-visible {
      z-index: 3;
      @include focus-ring(true, var(--theme-focus-ring, var(--focus-ring-color)));
    }

    &.active,
    .active > & {
      z-index: 3;
      color: var(--theme-contrast, var(--pagination-active-color));
      background-color: var(--theme-bg, var(--pagination-active-bg));
      border-color: var(--theme-bg, var(--pagination-active-border-color));
    }

    &.disabled,
    .disabled > & {
      color: var(--pagination-disabled-color);
      pointer-events: none;
      background-color: var(--pagination-disabled-bg);
      border-color: var(--pagination-disabled-border-color);
    }
  }

  .page-item {
    &:not(:first-child) .page-link {
      margin-inline-start: calc(-1 * var(--pagination-border-width));
    }

    &:first-child {
      .page-link {
        @include border-start-radius(var(--pagination-border-radius));
      }
    }

    &:last-child {
      .page-link {
        @include border-end-radius(var(--pagination-border-radius));
      }
    }
  }

  //
  // Sizing
  //

  // scss-docs-start pagination-sizes-loop
  @each $size, $_ in $pagination-sizes {
    .pagination-#{$size} {
      --pagination-min-height: var(--btn-input-#{$size}-min-height);
      --pagination-padding-y: var(--btn-input-#{$size}-padding-y);
      --pagination-padding-x: var(--btn-input-#{$size}-padding-x);
      --pagination-font-size: var(--btn-input-#{$size}-font-size);
      --pagination-border-radius: var(--btn-input-#{$size}-border-radius);
    }
  }

@each $size, $_ in $pagination-sizes {
  .pagination-#{$size} {
    --pagination-min-height: var(--btn-input-#{$size}-min-height);
    --pagination-padding-y: var(--btn-input-#{$size}-padding-y);
    --pagination-padding-x: var(--btn-input-#{$size}-padding-x);
    --pagination-font-size: var(--btn-input-#{$size}-font-size);
    --pagination-border-radius: var(--btn-input-#{$size}-border-radius);
  }
}

